    [[13,"喂？"]],
    [[17,"哦，你好。"],[39,"那是朱莉·戴维森吗？"]],
    [[11,"是的。"]],
    [[55,"这是来自就业机构的格雷格·普雷斯顿。"],[118,"上周当你来询问办公室工作相关的事时，我们见了面。"]],
    [[24,"哦，没错。"]],
    [[80,"现在我们刚刚收到了一些可能让你感兴趣的工作的详细信息。"]],
    [[10,"好的。"]],
    [[96,"所以这是接待员的职位——我觉得你以前做过这种工作吧？"]],
    [[112,"是的，我有。在结婚并生下孩子之前，我在一家体育中心工作了好几年。"]],
    [[13,"好的。"],[105,"嗯，这份工作在福特汉姆，所以离你并不太远。就在那里的医疗中心里。"]],
    [[11,"好的。"],[36,"那么，它具体在哪儿呢？"]],
    [[52,"它离车站很近，在查斯顿路。"]],
    [[13,"抱歉？"]],
    [[43,"Chastons Road 就是 C-H-A-S-T-O-N-S。"]],
    [[19,"好的，谢谢。"],[51,"那么这项工作会包括什么内容呢？"],[88,"处理患者的咨询？"]],
    [[100,"是的，你还将参与安排预约，无论是面对面还是通过电话。"],[135,"并在必要时重新安排时间。"]],
    [[41,"好的，那应该不会有问题。"]],
    [[84,"你的另一项职责就是保持中心数据库的更新。"],[182,"那么你可能还会承担其他一般的行政工作，但那些才是主要的工作内容。"]],
    [[10,"好的。"]],
    [[205,"现在当细节信息传过来时，我立刻想到了你，因为他们确实需要有经验的人，而你来见我们时确实提到了你在体育中心的工作。"]],
    [[40,"是的，事实上我非常喜欢那份工作。"],[83,"他们还在寻找其他东西吗？"]],
    [[250,"嗯，据说那里是一个压力很大的环境，大家总是非常忙碌，而患者也常常处于压力之下，所以他们需要一个人能够应对这些压力，保持冷静。同时，在与公众互动时也要充满自信。"]],
    [[93,"嗯，在照顾了三个都不到五岁的孩子之后，我觉得我能应付得来。"]],
    [[23,"我相信你一定能做到。"]],
    [[99,"然后他们还提到，他们在寻找具备优秀信息技术技能的人。"]],
    [[21,"没问题。"]],
    [[50,"那么你会对继续关注这件事感兴趣吗？"]],
    [[13,"当然。"],[33,"什么时候开始？"]],
    [[172,"嗯，他们正在寻找下个月初的人选，但我必须告诉您，这是临时安排，因此合同有效期只到九月底。"],[241,"但他们确实表示，在那之后可能还有更多机会。"]],
    [[38,"好的。那么工作时间会是多少呢？"]],
    [[103,"嗯，他们需要一个人能在早上八点一刻开始工作，你能做到吗？"]],
    [[134,"是的，我丈夫必须带孩子们去我母亲家——我上班时由她照顾他们。"],[159,"我什么时候能完成？"]],
    [[18,"十五点。"]],
    [[39,"那样应该会顺利解决。"],[122,"我可以在回家路上接上孩子们，然后就能和他们一起度过下午时光。"],[187,"哦，有一件事是中心有供员工使用的停车位吗？"]],
    [[49,"是的，有，而且它也位于一条公交线路上。"]],
    [[14,"好的。"],[75,"嗯，我预计会拿到那辆车，不过知道这一点也挺好。"],[106,"好的，那么接下来我该去哪里呢？"]],
    [[183,"嗯，如果你同意我这么做，我会把你的简历和推荐信发给他们，然后你最好直接打电话给他们，这样他们就能安排面试。"]],
    [[14,"很好。"],[39,"嗯，非常感谢。"]],
    [[22,"不客气。"],[30,"现在再见。"]],
    [[11,"再见。"]]
